import os,json,subprocess
from pathlib import Path
unit=Path("/etc/systemd/system/pm2-root.service")
archive=Path("/srv/projects/VPS/archive/retired-systemd-units")
dest=archive/"pm2-root.service"
out={"project":"VPS","status":"BLOCKED","changed":False}
made=False;moved=False
def run(a,env=None,t=12):return subprocess.run(a,capture_output=True,text=True,timeout=t,env=env)
def pids():
 ids={}
 for name,app in (("telegram-robot-leads","telegram-robot-leads"),("iptvpn-bot","iptvpn_bot")):
  root=Path("/srv/projects")/name
  cmd=["/usr/bin/node",str(root/"tools/pm2/bin/pm2"),"jlist"]
  p=run(cmd,dict(os.environ,PM2_HOME=str(root/".pm2")),18)
  if p.returncode:raise RuntimeError("private_pm2_not_accessible")
  x=json.loads(p.stdout)
  if len(x)!=1 or x[0].get("name")!=app or (x[0].get("pm2_env")or{}).get("status")!="online":raise RuntimeError("private_bot_not_running")
  ids[name]=x[0]["pid"]
 return ids
def services():return {name:run(["systemctl","is-active",name]).stdout.strip() for name in ("ssh","nginx","pink-vpn","lowcost-europa","pm2-telegram-robot-leads","pm2-iptvpn-bot")}
try:
 if not unit.is_file() or unit.is_symlink() or dest.exists() or dest.is_symlink():raise RuntimeError("legacy_service_or_target_missing")
 if not Path("/srv/projects/VPS").is_dir() or Path("/root/.pm2").exists():raise RuntimeError("global_pm2_not_archived")
 if run(["systemctl","is-active","pm2-root"]).stdout.strip()=="active" or run(["systemctl","is-enabled","pm2-root"]).stdout.strip()=="enabled":raise RuntimeError("old_global_pm2_still_running")
 for p in Path("/etc/systemd/system").rglob("*.service"):
  try:
   if p!=unit and p.is_file() and not p.is_symlink() and p.stat().st_size<120000 and b"pm2-root.service" in p.read_bytes():raise RuntimeError("another_unit_depends_on_old_pm2")
  except OSError:pass
 baseline=services();bot_pids=pids()
 archive.mkdir(mode=0o700,parents=True,exist_ok=False);made=True
 st=unit.stat()
 os.rename(unit,dest);moved=True
 after=dest.stat()
 if (st.st_dev,st.st_ino,st.st_uid,st.st_gid)!=(after.st_dev,after.st_ino,after.st_uid,after.st_gid):raise RuntimeError("systemd_unit_identity_changed")
 if run(["systemctl","daemon-reload"],t=20).returncode:raise RuntimeError("daemon_reload_failed")
 q=run(["systemctl","show","pm2-root","-p","LoadState","--value"])
 if q.stdout.strip() not in ("not-found","masked"):raise RuntimeError("obsolete_unit_still_loaded")
 if services()!=baseline or pids()!=bot_pids:raise RuntimeError("protected_service_or_bot_changed")
 out.update(status="GLOBAL_PM2_UNIT_RETIRED_VERIFIED",changed=True,archived_unit=str(dest),systemd_global_unit_absent=True,private_bots_unchanged=True,services_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:160]
 if moved:
  try:
   if dest.is_file() and not unit.exists():os.rename(dest,unit);out["rollback"]="UNIT_RESTORED"
   run(["systemctl","daemon-reload"],t=20)
  except Exception:out["rollback"]="INCOMPLETE"
 if made:
  try:
   if archive.is_dir() and not list(archive.iterdir()):archive.rmdir()
  except Exception:pass
print(json.dumps(out,sort_keys=True))
if out["status"]!="GLOBAL_PM2_UNIT_RETIRED_VERIFIED":raise SystemExit(3)
